onClick:
{{
  Insert_Ligne_Intervention.run()
    .then(() => {
      // 1. On ferme la modale
      closeModal('modal_add_ligne');

      // 2. On vide les champs pour la prochaine fois
      resetWidget('sel_article', true);
      resetWidget('inp_add_qte', true);

      // 3. On rafraîchit le tableau des lignes
      return Get_Lignes_Intervention.run();
    })
    .then(() => {
      // 4. On rafraîchit le Bon de Livraison global
      return Get_Detail_Intervention.run();
    })
    .then(() => {
      showAlert('Article ajouté !', 'success');
    })
    .catch((err) => {
      showAlert("Erreur lors de l'ajout", 'error');
      console.error(err);
    });
}}
